with ins as (insert into public.artist_aliases (artist_slug,alias,kind,source_url) select x.s,x.a,x.k,x.u from json_to_recordset('[{"s":"nishant-mittal","a":"Digging In India","k":"also_known_as","u":"https://magneticfields.in/artists/nishant-mittal"},{"s":"okedo","a":"Okedolo (duo with Dolorblind)","k":"also_known_as","u":"https://www.thewildcity.com/news/19853-okedo-dolorblind-introduce-their-duo-okedolo-with-ep-season-1"},{"s":"prismer","a":"Don Jiro","k":"also_known_as","u":"https://ra.co/dj/prismer"},{"s":"anish-sood","a":"Anyasa","k":"also_known_as","u":"https://en.wikipedia.org/wiki/Anish_Sood"},{"s":"film","a":"Tyrell Dub Corp","k":"also_known_as","u":"https://www.thewildcity.com/artists/4504-film"},{"s":"film","a":"MO/SS (live duo with Shaun Moses)","k":"also_known_as","u":"https://www.thewildcity.com/artists/4504-film"}]'::json) as x(s text,a text,k text,u text) join public.artists a on a.slug=x.s on conflict (artist_slug,alias) do nothing returning 1) select count(*) from ins;